/* Account hub, part 2: the one Repositories area (D30), a repository's pages by role, the copy wizard, the update inbox, releases, and Discover. */
HUB.repos.forEach((r) => { if (!r.people) r.people = r.mine ? [{ name: 'Dana Okafor', role: r.mine, you: true, by: '' }, { name: 'Ken Oyelaran', role: 'Author', by: 'Dana Okafor' }] : []; if (!r.releases) r.releases = r.mine && r.state === 'Published' ? HUB.releases.map((x) => ({ ...x })) : []; });
H.upd = {};
const repoRole = (r) => (r.mine ? (H.role === 'asis' ? r.mine : (H.role === 'Player' ? null : H.role)) : null);
const myAdminLibs = (r) => HUB.libraries.filter((l) => (l.repos.includes(r.id) || r.usedBy.includes(l.id)) && isAdmin(libRole(l)));

/* ---------------------------------------------------------------- the list: one area, your role decides what you see */
function pRepositories() {
  const q = (H.repoQ || '').toLowerCase();
  const pub = HUB.repos.filter((r) => r.mine && r.name.toLowerCase().includes(q));
  const used = HUB.repos.filter((r) => !r.mine && r.name.toLowerCase().includes(q));
  const usedRows = used.map((r) => { const libs = r.usedBy.map((id) => hl(id).name).join(', '); return repoRow(r, ` · ${libs}`); }).join('') || '<div class="empty-inline">No repository matches.</div>';
  const pubRows = pub.map((r) => repoRow(r, ` · ${r.libs} ${r.libs === 1 ? 'library uses' : 'libraries use'} it`)).join('') || '<div class="empty-inline">No repository matches.</div>';
  return `<div class="page page--wide page-enter"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Repositories</h1><p class="page-sub" style="margin-bottom:0">What your libraries draw on, and what you publish.</p></div>${H.create ? `<button type="button" class="btn btn--primary" data-act="new-repo">${ic('add')}Create a repository</button>` : ''}</div>
  <div class="toolbar" style="margin-top:var(--s-3)"><div class="search"><span class="visually-hidden"><label for="rq">Search repositories</label></span>${ic('search')}<input id="rq" class="input" type="search" placeholder="Search repositories" value="${esc(H.repoQ || '')}" data-act="repo-q" autocomplete="off"></div></div>
  <div class="hx2"><section aria-labelledby="r-used"><div class="sec-h"><h2 id="r-used">Your libraries draw on</h2></div><div class="listcard">${usedRows}</div></section><section aria-labelledby="r-pub"><div class="sec-h"><h2 id="r-pub">You publish</h2></div><div class="listcard">${pubRows}</div>${H.create ? '' : '<p class="t-meta" style="margin-top:var(--s-2h)">Creating a repository is not open to your account yet.</p>'}</section></div></div>`;
}
function afterRepositories() { hubAfter(); const q = $('#rq'); q.oninput = () => { H.repoQ = q.value; const pos = q.selectionStart; refresh(); const n = $('#rq'); n.focus(); n.setSelectionRange(pos, pos); }; }

/* ---------------------------------------------------------------- one repository */
function repoTabs(r, role) {
  const t = [['overview', 'Overview']];
  if (myAdminLibs(r).length) t.push(['use', 'Use in a library']);
  if (isAdmin(role)) t.push(['profile', 'Profile']);
  if (role) t.push(['people', 'People']);
  if (isAdmin(role)) t.push(['releases', 'Releases'], ['using', 'Libraries using it']);
  return t;
}
function pRepo() {
  const [, id, tab0] = parts(); const r = hr(id) || HUB.repos[0]; const role = repoRole(r);
  const tabs = repoTabs(r, role); const tab = tabs.some((t) => t[0] === tab0) ? tab0 : 'overview';
  const body = { overview: repoOverview, use: repoUse, profile: repoProfile, people: (x, ro) => peopleBlock(x, ro, 'repository'), releases: repoReleases, using: repoUsing }[tab](r, role);
  const vis = r.visibility === 'Public' ? `<span class="chip">${ic('globe')}Public</span>` : `<span class="vis">${ic('private')}Private</span>`;
  return `<div class="page page--wide page-enter"><p class="crumb"><a href="#/repositories">Repositories</a> / ${esc(r.name)}</p><div class="head-row"><div class="grow"><h1 class="t-title">${esc(r.name)}</h1><p class="muted" style="margin-top:4px">By ${esc(r.by)} · ${role ? 'You are ' + (role === 'Owner' ? 'the Owner' : role === 'Organizer' ? 'an Organizer' : 'an Author') : 'Offered to your library'}</p></div><span class="row2">${repoChip(r)}${vis}</span></div><div class="subtabs" role="tablist" aria-label="${esc(r.name)}">${tabs.map(([k, n]) => `<button type="button" class="subtab" role="tab" aria-selected="${k === tab}" data-go="repo/${r.id}/${k}">${n}</button>`).join('')}</div>${body}</div>`;
}
function builtOnOutline(r) {
  if (!r.builtOn.length) return '<p class="muted">It is not built on another repository.</p>';
  return `<ul class="outline-tree" style="list-style:none;margin:0;padding:0">${r.builtOn.map((id) => { const b = hr(id); const state = b.rel === 'used' && b.copied !== false ? ['Copied', 'synced', 'select-item'] : ['Invited, not copied', '', 'pending']; return `<li style="border-left:2px solid var(--border-subtle);padding:6px 0 6px 12px"><span class="row2"><b>${esc(b.name)}</b><span class="st ${state[1] ? 'st--' + state[1] : ''}">${ic(state[2])}<span>${state[0]}</span></span></span></li>`; }).join('')}</ul><p class="t-meta" style="margin-top:6px">A repository can be built on others. A library must be invited to each one; invitations are not passed on.</p>`;
}
function repoOverview(r, role) {
  const c = r.counts;
  const live = r.visibility === 'Private' && r.state === 'Published' && role ? hubCallout('live', '<b>Live.</b> Libraries that copy from this repository see your edits when they next check for updates.') : '';
  const draft = r.state === 'Draft' && role ? hubCallout('info', '<b>Draft.</b> It is not offered to any library until you publish a release.') : '';
  const inside = ['Rope, 15 m', 'Field jacket', 'Winter coat', 'Repair kit', 'Lantern, hooded', 'Short blade'];
  return `<div class="col-gap" style="max-width:1000px">${live}${draft}<p class="t-body" style="max-width:640px">${esc(r.summary)}</p><div class="grid cont"><div class="stat-tile"><div class="t-meta">Entries</div><div class="v num">${c.entries}</div></div><div class="stat-tile"><div class="t-meta">Stat groups and stats</div><div class="v num">${c.groups} · ${c.stats}</div></div><div class="stat-tile"><div class="t-meta">Notes</div><div class="v num">${c.notes}</div></div></div><div class="hx2"><section><div class="sec-h"><h2>Built on</h2></div>${builtOnOutline(r)}</section><section><div class="sec-h"><h2>What is inside</h2></div><div class="listcard">${inside.map((n) => `<div class="item-row">${ic('kind-item')}${esc(n)}<span class="t-meta" style="margin-left:auto">Item</span></div>`).join('')}</div><p class="t-meta" style="margin-top:6px">${role ? 'You see everything you wrote.' : 'Only names show until your library copies it.'}</p></section></div></div>`;
}

/* ---------------------------------------------------------------- Use in a library: copy, then the update inbox */
function repoUse(r) {
  const libs = myAdminLibs(r); const l = hl(H.useLib && libs.some((x) => x.id === H.useLib) ? H.useLib : libs[0].id);
  const sel = libs.length > 1 ? `<div class="row2" style="margin-bottom:var(--s-3)"><span class="label" style="margin:0">Library</span><div class="seg" role="radiogroup" aria-label="Library">${libs.map((x) => `<button type="button" role="radio" aria-checked="${x.id === l.id}" data-act="use-lib" data-v="${x.id}">${esc(x.name)}</button>`).join('')}</div></div>` : '';
  let body;
  if (r.rel === 'gone') body = hubCallout('retired', `<b>No longer offered.</b> ${esc(r.by)} stopped offering ${esc(r.name)}. Your copy stays and so do its contents; there will be no more updates.`);
  else if (r.rel === 'invited' && !r.copied) body = `<div class="card col-gap" style="max-width:640px"><h2 class="t-heading">Copy ${esc(r.name)} into ${esc(l.name)}</h2><p class="muted">${esc(r.counts.entries)} entries, ${r.counts.groups} stat groups and ${r.counts.stats} stats. A check comes first: nothing changes until you say so.</p><div><button type="button" class="btn btn--primary" data-act="copy" data-r="${r.id}" data-l="${l.id}">Check first</button></div></div><div style="margin-top:var(--s-4)"><div class="sec-h"><h2>Built on</h2></div>${builtOnOutline(r)}</div>`;
  else if (r.update && r.copied !== false) body = updateInbox(r, l);
  else body = `<div class="empty-inline">${ic('select-item', 'lg')}<div class="t-sub" style="margin-top:var(--s-2h)">${esc(l.name)} is up to date</div><div class="muted">Nothing new in ${esc(r.name)} since the last update.</div></div>`;
  return sel + body;
}
function updateInbox(r, l) {
  const groups = Object.entries(HUB.updates); const remaining = groups.reduce((n, [, rows]) => n + rows.filter((x) => !H.upd[x.id]).length, 0);
  const cleanIds = groups.flatMap(([, rows]) => rows.filter((x) => !H.upd[x.id] && (x.clean || x === rows[0] && false || rows === HUB.updates.New)).map((x) => x.id));
  const u = r.update;
  if (!remaining) return `<div class="empty-inline">${slot('caught-up', 'Catileo, curled sleep')}<div class="t-sub" style="margin-top:var(--s-2h)">All caught up</div><div class="muted">${esc(l.name)} has every update from ${esc(r.name)}.</div></div>`;
  return `<div class="col-gap"><div class="head-row"><div class="grow"><h2 class="t-heading">${esc(r.name)}: ${u.changed} changed, ${u.added} new, ${u.removed} removed upstream, ${u.conflicts} conflicts</h2><p class="muted" style="margin-top:4px">Descriptions and notes are copied once and never updated.</p></div><button type="button" class="btn btn--primary" data-act="apply-clean" data-r="${r.id}" ${cleanIds.length ? '' : 'aria-disabled="true"'}>Apply all clean (${cleanIds.length})</button></div>${hubCallout('info', '<b>Applying changes what players see.</b> Nothing applies by itself. “Apply all clean” leaves out anything you changed, anything that breaks, and anything that attaches to entries you already have.')}${groups.map(([g, rows]) => `<section aria-labelledby="g-${g.replace(/\s/g, '')}"><div class="sec-h"><h2 id="g-${g.replace(/\s/g, '')}" class="t-ui" style="font-weight:600">${g}</h2><span class="t-meta">${rows.filter((x) => !H.upd[x.id]).length} left</span></div><div class="listcard"><div class="diff diff-head" aria-hidden="true"><span>What</span><span>Was</span><span>Now</span><span>Yours</span><span></span></div>${rows.map((x) => diffRow(x, g)).join('')}</div></section>`).join('')}</div>`;
}
function diffRow(x, g) {
  const done = H.upd[x.id];
  const acts = done ? `<span class="st st--synced">${ic('select-item')}<span>${{ applied: 'Applied', skipped: 'Skipped', detached: 'Detached' }[done]}</span></span>` : `<span class="acts"><button type="button" class="btn" data-act="upd" data-id="${x.id}" data-v="applied">Apply</button>${g === 'Removed upstream' ? `<button type="button" class="btn" data-act="upd" data-id="${x.id}" data-v="detached">Detach</button>` : ''}<button type="button" class="btn btn--quiet" data-act="upd" data-id="${x.id}" data-v="skipped">Skip</button></span>`;
  return `<div class="diff"><div><b>${esc(x.what)}</b><div class="t-meta">${esc(x.label)}</div></div><div><span class="k">Was</span>${esc(x.from || '—')}</div><div><span class="k">Now</span>${esc(x.now)}</div><div><span class="k">Yours</span>${esc(x.yours || '—')}</div>${acts}</div>`;
}

/* the copy wizard: four steps, one primary button each */
function openCopyWizard(r, libName, done) {
  const steps = ['Check first', 'Name clashes', 'Review', 'Done']; let i = 0; let choice = 'existing';
  const d = openDialog({ title: `Copy ${esc(r.name)} into ${esc(libName)}`, wide: true, body: '<div id="wz"></div>', actions: [] });
  const wz = $('#wz', d); const bar = () => `<ol class="stepper" aria-label="Steps">${steps.map((s, k) => `<li ${k === i ? 'aria-current="step"' : ''}>${k < i ? ic('select-item') : ''}${k + 1}. ${s}</li>`).join('')}</ol>`;
  const nav = (back, next, nextLabel, disabled) => `<div class="actions">${back ? '<button type="button" class="btn" data-wz="back">Back</button>' : '<button type="button" class="btn" data-wz="cancel">Cancel</button>'}<button type="button" class="btn btn--primary" data-wz="next" ${disabled ? 'aria-disabled="true"' : ''}>${nextLabel}</button></div>`;
  const draw = () => {
    if (i === 0) { wz.innerHTML = bar() + `<div class="col-gap" role="status" aria-label="Checking"><div class="row2">${ic('refresh', 'spin')}Checking what would be copied…</div><div class="skel" style="width:70%"></div><div class="skel" style="width:50%"></div></div>`; setTimeout(() => { if (!wz.isConnected) return; wz.innerHTML = bar() + `<div class="col-gap"><p class="t-body">Copying <b>${esc(r.name)}</b> would add:</p><div class="grid cont"><div class="stat-tile"><div class="t-meta">Entries</div><div class="v num">${r.counts.entries}</div></div><div class="stat-tile"><div class="t-meta">Stat groups and stats</div><div class="v num">${r.counts.groups} · ${r.counts.stats}</div></div><div class="stat-tile"><div class="t-meta">Name clashes</div><div class="v num">1</div></div></div>${hubCallout('warning', '<b>A copy cannot be undone as a whole.</b> A library can only remove what it copied piece by piece, or copy again and purge, which also removes its own additions to those entries. A library works with one game system at a time for now.', 'warn')}</div>${nav(false, true, 'Next: name clashes')}`; }, 700); }
    else if (i === 1) wz.innerHTML = bar() + `<div class="col-gap"><div class="head-row"><div class="grow"><p class="t-body">1 name clash</p></div><button type="button" class="btn" data-wz="rec">Do what is recommended for all</button></div><section class="card col-gap"><h3 class="t-sub">Your library already has a stat called <i>Weight</i></h3><div class="col-gap" role="radiogroup" aria-label="What to do">${[['both', 'Keep both', 'Add the new one beside yours, with a different name.'], ['existing', 'Use the existing one', 'Recommended. Entries use the stat you already have.'], ['skip', 'Leave it out', 'Do not copy this stat.']].map(([v, t, m]) => `<label class="card" style="display:flex;gap:10px;cursor:pointer;${choice === v ? 'border-color:var(--border-control);background:var(--surface-selected)' : ''}"><input type="radio" name="clash" value="${v}" ${choice === v ? 'checked' : ''} style="margin-top:4px"><span><b>${t}</b>${v === 'existing' ? ' <span class="chip">Recommended</span>' : ''}<span class="t-meta" style="display:block">${m}</span></span></label>`).join('')}</div></section></div>${nav(true, true, 'Next: review')}`;
    else if (i === 2) wz.innerHTML = bar() + `<div class="col-gap"><p class="t-body"><b>Would add ${r.counts.entries} entries, use 2 existing stats, ${choice === 'both' ? 'keep both of 1' : choice === 'existing' ? 'use the existing one for 1' : 'leave out 1'}.</b><br>Nothing has changed yet.</p><details class="card"><summary style="cursor:pointer;min-height:var(--hit);display:flex;align-items:center">The full list</summary><p class="t-meta" style="margin-top:8px">${r.counts.entries} entries, ${r.counts.groups} stat groups, ${r.counts.stats} stats. The names are listed here in the real design.</p></details></div>${nav(true, true, 'Copy now')}`;
    else { wz.innerHTML = bar() + `<div class="col-gap" role="status"><div class="progress-bar" aria-label="Copying"><span id="wz-bar" style="width:0%"></span></div><p class="muted">Copying ${esc(r.name)} into ${esc(libName)}…</p></div>`; requestAnimationFrame(() => { const b = $('#wz-bar', wz); if (b) b.style.width = '100%'; }); setTimeout(() => { if (!wz.isConnected) return; r.copied = true; wz.innerHTML = bar() + `<div class="col-gap"><div class="row2">${ic('select-item', 'lg')}<b class="t-sub">Copied ${r.counts.entries} entries into ${esc(libName)}</b></div><p class="muted">You can find them in the library. “Copy again” is in the page’s menu.</p></div><div class="actions"><button type="button" class="btn btn--primary" data-wz="finish" data-autofocus>See it in ${esc(libName)}</button></div>`; const f = $('[data-wz="finish"]', wz); if (f) f.focus(); }, 1500); }
  };
  d.addEventListener('click', (e) => { const a = e.target.closest('[data-wz]'); if (!a || a.getAttribute('aria-disabled') === 'true') return; const k = a.dataset.wz; if (k === 'cancel') closeOv(); else if (k === 'back') { i--; draw(); } else if (k === 'next') { i++; draw(); } else if (k === 'rec') { choice = 'existing'; draw(); } else if (k === 'finish') { closeOv(); if (done) done(); } });
  d.addEventListener('change', (e) => { if (e.target.name === 'clash') { choice = e.target.value; draw(); const c = $('input[name="clash"]:checked', wz); if (c) c.focus(); } });
  draw();
}

/* ---------------------------------------------------------------- Profile, Releases, Libraries using it */
function repoProfile(r, role) {
  const ed = isAdmin(role); const dis = ed ? '' : 'disabled';
  return `<div class="form" data-form><section class="form-sec"><div><h2 class="t-heading">Profile</h2><p class="muted" style="margin-top:4px">What people see when they find it.</p></div><div class="fields"><div><label class="label" for="p-s">Summary</label><textarea id="p-s" class="input" rows="3" data-f style="padding:8px 12px">${esc(r.summary)}</textarea></div><div><span class="label">Cover</span><div class="cover" role="img" aria-label="Cover picture slot">Cover picture<br>3 : 1</div></div><div><label class="label" for="p-l">Licence</label><span class="selectwrap"><select id="p-l" class="select" data-f><option>All rights reserved</option><option selected>CC BY 4.0</option><option>CC BY-SA 4.0</option></select>${ic('expand')}</span></div><div><label class="label" for="p-c">Credits</label><input id="p-c" class="input" data-f value="${esc(r.by)} and friends"></div><div><label class="label" for="p-t">Tags</label><input id="p-t" class="input" data-f value="${esc(r.tags.join(', '))}"><div class="help">Separate with commas.</div></div><div><label class="label" for="p-g">Game system</label><input id="p-g" class="input" data-f value="${esc(r.system)}"></div><div><label class="label" for="p-n">Languages</label><input id="p-n" class="input" data-f value="${esc(r.lang)}"></div></div></section>${ed ? '' : ''}</div>`;
}
function repoReleases(r, role) {
  const owner = role === 'Owner';
  const next = r.releases.length ? (parseFloat(r.releases[0].label) + 0.1).toFixed(1) : '1.0';
  const list = r.releases.length ? r.releases.map((x) => `<div class="item-row"><span class="grow"><span class="nm">${esc(x.label)}</span> ${x.breaking ? '<span class="st st--waiting">' + ic('warning') + '<span>Breaking</span></span>' : ''}<span class="t-meta" style="display:block">${esc(x.when)} · ${esc(x.notes)}</span></span></div>`).join('') : '<div class="empty-inline">No release yet. Libraries are offered a repository when you publish its first release.</div>';
  const reason = owner ? '' : '<p class="t-meta" style="margin-top:8px">Only an Owner can publish.</p>';
  return `<div class="hx2"><section aria-labelledby="rl-l"><div class="sec-h"><h2 id="rl-l">Releases</h2></div><div class="listcard">${list}</div></section><section class="card col-gap" aria-labelledby="rl-n"><h2 id="rl-n" class="t-heading">${r.state === 'Draft' ? 'Publish the first release' : 'Compose a release'}</h2><div><label class="label" for="rl-label">Label</label><input id="rl-label" class="input" value="${next}"></div><div><label class="label" for="rl-notes">Notes</label><textarea id="rl-notes" class="input" rows="3" style="padding:8px 12px" placeholder="What changed, in a sentence"></textarea></div><div class="row2"><button type="button" class="switch" role="switch" aria-checked="false" aria-label="This release breaks copies" id="rl-brk"></button><span>This release breaks copies</span></div><p class="t-meta">Since ${r.releases[0] ? r.releases[0].label : 'the start'}: 12 entries changed, 3 added, 1 removed.</p><div class="row2"><button type="button" class="btn btn--primary" data-act="publish" data-r="${r.id}" ${owner ? '' : 'aria-disabled="true"'}>${r.state === 'Draft' ? 'Publish…' : 'Publish release…'}</button>${r.state === 'Published' ? `<button type="button" class="btn" data-act="unpublish" data-r="${r.id}" ${owner ? '' : 'aria-disabled="true"'}>Unpublish…</button>` : ''}</div>${reason}<hr class="hr" style="margin:0"><div class="head-row"><div class="grow"><b>Visibility: ${r.visibility}</b><p class="t-meta">${r.visibility === 'Private' ? 'Only libraries you invite can copy it.' : 'Anyone signed in can find it in Discover.'}</p></div><button type="button" class="btn" data-act="visibility" data-r="${r.id}" ${owner ? '' : 'aria-disabled="true"'}>${r.visibility === 'Private' ? 'Make public…' : 'Make private…'}</button></div></section></div>`;
}
function repoUsing(r, role) {
  const owner = role === 'Owner';
  const rows = r.usedBy.map((id) => { const l = hl(id); return `<div class="tr" style="grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) 130px"><span class="nm">${esc(l.name)}</span><span><span class="lbl">Invited</span>3 weeks ago</span><span><span class="lbl">Copied</span>Yes</span><span><span class="lbl">Release</span>${r.release || '—'}</span><span>${owner ? `<button type="button" class="btn btn--quiet" data-act="stop-invite" data-r="${r.id}" data-l="${l.id}">Stop inviting</button>` : ''}</span></div>`; }).join('') || '<div class="tr"><span class="muted">No library yet. Invite one to start.</span></div>';
  return `<div class="col-gap"><div class="head-row"><p class="muted grow">${r.libs} ${r.libs === 1 ? 'library has' : 'libraries have'} an invitation or a copy.</p><span class="row2"><button type="button" class="btn" data-act="view-sub" data-r="${r.id}">View as a subscriber</button><button type="button" class="btn btn--primary" data-act="invite-lib" data-r="${r.id}" ${owner ? '' : 'aria-disabled="true"'}>Invite a library</button></span></div><div class="tbl2"><div class="th" style="grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) 130px"><span>Library</span><span>Invited</span><span>Copied</span><span>Release</span><span></span></div>${rows}</div>${owner ? '' : '<p class="t-meta">Only an Owner can invite libraries.</p>'}</div>`;
}
function openNewRepo() {
  openDialog({ title: 'Create a repository', body: `<div class="col-gap"><div><label class="label" for="nr-n">Name</label><input id="nr-n" class="input" data-autofocus value="Night markets"></div><div><label class="label" for="nr-s">Link name</label><input id="nr-s" class="input t-code" value="night-markets"></div><div><label class="label" for="nr-d">Description</label><input id="nr-d" class="input" value="Stalls, hours and who owes whom"></div><p class="t-meta">A repository is a space whose content libraries copy. It has no campaigns and no players.</p></div>`, actions: [{ label: 'Cancel' }, { label: 'Create repository', kind: 'primary', fn: (d) => { const n = $('#nr-n', d).value.trim() || 'Untitled'; const id = $('#nr-s', d).value.trim() || 'untitled'; HUB.repos.unshift({ id, name: n, by: DATA.user.name, summary: $('#nr-d', d).value, state: 'Draft', release: '', rel: 'publish', mine: 'Owner', visibility: 'Private', tags: [], system: 'Any system', lang: 'English', update: null, usedBy: [], libs: 0, counts: { entries: 0, groups: 0, stats: 0, notes: 0 }, builtOn: [], people: [{ name: DATA.user.name, role: 'Owner', you: true, by: '' }], releases: [] }); toast({ title: `${n} created` }); go('repo/' + id); } }] });
}
Object.assign(window, { HUB_ACTS2: {
  'use-lib': (a) => { H.useLib = a.dataset.v; refresh(); },
  copy: (a) => { const r = hr(a.dataset.r), l = hl(a.dataset.l); openCopyWizard(r, l.name, () => { toast({ title: `${r.name} copied`, text: `Into ${l.name}.` }); refresh(); }); },
  upd: (a) => { H.upd[a.dataset.id] = a.dataset.v; refresh(); toast({ title: { applied: 'Applied', skipped: 'Skipped', detached: 'Detached' }[a.dataset.v] }); },
  'apply-clean': (a) => { if (a.getAttribute('aria-disabled') === 'true') return; const ids = Object.values(HUB.updates).flatMap((rows) => rows.filter((x) => !H.upd[x.id] && (x.clean || rows === HUB.updates.New)).map((x) => x.id)); confirmSimple(`Apply ${ids.length} clean updates?`, `They add or change entries you have not edited. Players will see them. Anything you changed, anything that breaks, and anything that attaches to entries you already have stays for you to decide.`, `Apply ${ids.length}`, () => { ids.forEach((id) => (H.upd[id] = 'applied')); refresh(); toast({ title: `Applied ${ids.length} updates` }); }, false); },
  publish: (a) => { if (a.getAttribute('aria-disabled') === 'true') return; const r = hr(a.dataset.r); const label = ($('#rl-label') || {}).value || '1.0'; const brk = ($('#rl-brk') || {}).getAttribute && $('#rl-brk').getAttribute('aria-checked') === 'true'; openDialog({ title: `Publish ${esc(r.name)} ${esc(label)}?`, body: `<div class="col-gap"><p class="muted t-body">${r.libs} ${r.libs === 1 ? 'library' : 'libraries'} will be told there is a new release. Updates never apply by themselves.</p>${hubCallout('info', r.builtOn.length ? `<b>Built on ${r.builtOn.map((id) => esc(hr(id).name)).join(', ')}.</b> It is published, so a copy of this repository works.` : '<b>It is built on nothing,</b> so nothing else needs to be published first.')}${hubCallout('info', '<b>Notes marked GM only travel with a copy.</b> Libraries decide who reads them.')}${brk ? hubCallout('warning', '<b>You marked this release as breaking.</b> Libraries are told to review it before they update.', 'warn') : ''}</div>`, actions: [{ label: 'Cancel', auto: true }, { label: 'Publish', kind: 'primary', fn: () => { r.state = 'Published'; r.release = label; r.rel = 'publish'; r.releases.unshift({ label, when: 'Just now', breaking: !!brk, notes: ($('#rl-notes') || {}).value || 'A new release.' }); refresh(); toast({ title: `${r.name} ${label} published` }); } }] }); },
  unpublish: (a) => { if (a.getAttribute('aria-disabled') === 'true') return; const r = hr(a.dataset.r); confirmSimple(`Unpublish ${r.name}?`, `${r.libs} libraries will be told. Libraries that already copied it keep their copies; they stop getting updates until you publish again.`, 'Unpublish', () => { r.state = 'Draft'; refresh(); toast({ title: `${r.name} is a draft again` }); }); },
  visibility: (a) => { if (a.getAttribute('aria-disabled') === 'true') return; const r = hr(a.dataset.r); const toPublic = r.visibility === 'Private'; const blocked = toPublic && r.builtOn.some((id) => hr(id).visibility !== 'Public'); openDialog({ title: toPublic ? `Make ${esc(r.name)} public?` : `Make ${esc(r.name)} private?`, body: `<div class="col-gap">${toPublic ? `<p class="muted t-body">Anyone signed in will be able to find it in Discover and look at its storefront. A first public release is made with the switch.</p>` : `<p class="muted t-body">It leaves Discover. ${r.libs} libraries that copied it keep their copies and stop getting updates from the public release.</p>`}<p class="t-body">${r.libs} ${r.libs === 1 ? 'library is' : 'libraries are'} affected.</p>${blocked ? hubCallout('warning', `<b>${esc(r.builtOn.map((id) => hr(id).name).join(', '))} must be public first.</b> A public repository can only be built on public ones.`, 'warn') : ''}</div>`, actions: [{ label: 'Cancel', auto: true }, { label: toPublic ? 'Make public' : 'Make private', kind: 'primary', disabled: blocked, fn: () => { r.visibility = toPublic ? 'Public' : 'Private'; refresh(); toast({ title: `${r.name} is now ${r.visibility.toLowerCase()}` }); } }] }); },
  'stop-invite': (a) => { const r = hr(a.dataset.r), l = hl(a.dataset.l); confirmSimple(`Stop inviting ${l.name}?`, `${l.name} keeps its copy and everything in it. It gets no more updates, and its admins are told.`, 'Stop inviting', () => { r.usedBy = r.usedBy.filter((x) => x !== l.id); r.libs--; refresh(); toast({ title: `No longer offered to ${l.name}` }); }); },
  'invite-lib': (a) => { if (a.getAttribute('aria-disabled') === 'true') return; showOnce('Invite a library', 'Send this link to an Owner of the library you want to invite. It is shown now and never again.', fakeLink(), 'It works once and ends in a week. Anyone with an invitation can copy the repository.'); },
  'view-sub': (a) => { const r = hr(a.dataset.r); toast({ title: 'A test library is ready', text: `You own it, and it is invited to ${r.name}. Its Shelf shows what an admin sees.` }); },
  'repo-q': () => {}
} });
document.addEventListener('click', (e) => { const b = e.target.closest('#rl-brk'); if (b) b.setAttribute('aria-checked', b.getAttribute('aria-checked') === 'true' ? 'false' : 'true'); });

/* ---------------------------------------------------------------- Discover: its own place (D30) */
function pDiscover() {
  if (!S.publicRepos) return `<div class="stub page-enter">${ic('globe', 'lg')}<h1 class="t-title">Discover</h1><p class="muted">Public repositories are not turned on here.</p><a class="btn" href="#/hub">Go to Home</a></div>`;
  const [, id] = parts(); if (id) return pStorefront(id);
  const q = (H.disc.q || '').toLowerCase(); const tags = ['All', ...new Set(HUB.discover.flatMap((d) => d.tags))]; const langs = ['All', ...new Set(HUB.discover.map((d) => d.lang))];
  const list = HUB.discover.filter((d) => (d.name + d.summary).toLowerCase().includes(q) && (H.disc.tag === 'All' || d.tags.includes(H.disc.tag)) && (H.disc.lang === 'All' || d.lang === H.disc.lang));
  const cards = list.map((d) => `<a class="card tile repo-card" href="#/discover/${d.id}"><div class="cover" aria-hidden="true">Cover</div><b class="t-sub">${esc(d.name)}</b><span class="t-meta">By ${esc(d.by)} · release ${d.release} · ${d.libs} libraries</span><span class="muted">${esc(d.summary)}</span><span class="row2">${d.tags.map((t) => `<span class="tag">${esc(t)}</span>`).join('')}</span></a>`).join('') || `<div class="state-cell" style="grid-column:1/-1">${ic('search')}<div class="t-sub">No repository matches</div><div class="muted">Try a different word, or clear the filters.</div><div class="acts"><button type="button" class="btn" data-act="disc-clear">Clear filters</button></div></div>`;
  return `<div class="page page--wide page-enter"><h1 class="t-title page-title">Discover</h1><p class="page-sub">Public repositories you can look inside and copy into a library.</p><div class="toolbar"><div class="search"><span class="visually-hidden"><label for="dq">Search public repositories</label></span>${ic('search')}<input id="dq" class="input" type="search" placeholder="Search public repositories" value="${esc(H.disc.q)}" autocomplete="off"></div><span class="selectwrap" style="width:180px"><select class="select" id="dt" aria-label="Tag">${tags.map((t) => `<option ${t === H.disc.tag ? 'selected' : ''} value="${esc(t)}">${t === 'All' ? 'Any tag' : esc(t)}</option>`).join('')}</select>${ic('expand')}</span><span class="selectwrap" style="width:180px"><select class="select" id="dl" aria-label="Language">${langs.map((t) => `<option ${t === H.disc.lang ? 'selected' : ''} value="${esc(t)}">${t === 'All' ? 'Any language' : esc(t)}</option>`).join('')}</select>${ic('expand')}</span></div><div class="grid three stagger" style="margin-top:var(--s-3)">${cards}</div></div>`;
}
function afterDiscover() { hubAfter(); const q = $('#dq'); if (!q) return; q.oninput = () => { H.disc.q = q.value; const p = q.selectionStart; refresh(); const n = $('#dq'); n.focus(); n.setSelectionRange(p, p); }; $('#dt').onchange = (e) => { H.disc.tag = e.target.value; refresh(); }; $('#dl').onchange = (e) => { H.disc.lang = e.target.value; refresh(); }; }
function pStorefront(id) {
  const d = HUB.discover.find((x) => x.id === id) || HUB.discover[0]; const libs = HUB.libraries.filter((l) => isAdmin(libRole(l)));
  return `<div class="page page--capped page-enter"><p class="crumb"><a href="#/discover">Discover</a> / ${esc(d.name)}</p><div class="cover" style="height:180px;margin-bottom:var(--s-3)" role="img" aria-label="Cover picture slot">Cover picture</div><div class="head-row"><div class="grow"><h1 class="t-title">${esc(d.name)}</h1><p class="muted" style="margin-top:4px">By ${esc(d.by)} · ${esc(d.system)} · ${esc(d.lang)}</p></div><span class="chip">${ic('globe')}Public</span></div><p class="t-body" style="max-width:640px;margin:var(--s-3) 0">${esc(d.summary)}</p><div class="row2" style="margin-bottom:var(--s-4)">${d.tags.map((t) => `<span class="tag">${esc(t)}</span>`).join('')}<span class="t-meta">Release ${d.release} · ${d.libs} libraries use it</span></div><div class="hx2"><section><div class="sec-h"><h2>Look inside</h2></div><div class="listcard">${['Rope, 15 m', 'Field jacket', 'Winter coat', 'Repair kit', 'Lantern, hooded'].map((n) => `<div class="item-row">${ic('kind-item')}${n}<span class="t-meta" style="margin-left:auto">Item</span></div>`).join('')}</div><p class="t-meta" style="margin-top:6px">This is the release’s preview, chosen by its owner. It is not the live repository.</p></section><section class="card col-gap"><h2 class="t-heading">Copy it into a library</h2>${libs.length ? `<p class="muted">Choose a library you run. A check comes first and nothing changes until you say so.</p><div class="selectwrap"><select class="select" id="dc-l" aria-label="Library">${libs.map((l) => `<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select>${ic('expand')}</div><div><button type="button" class="btn btn--primary" data-act="disc-copy" data-id="${d.id}">Check first</button></div>` : `<p class="muted">You need to be an Owner or an Organizer of a library to copy a repository.</p>`}</section></div></div>`;
}
Object.assign(window.HUB_ACTS2, { 'disc-clear': () => { H.disc = { q: '', tag: 'All', lang: 'All' }; refresh(); }, 'disc-copy': (a) => { const d = HUB.discover.find((x) => x.id === a.dataset.id); const l = hl($('#dc-l').value); openCopyWizard({ name: d.name, counts: { entries: 142, groups: 4, stats: 17, notes: 0 }, id: d.id }, l.name, () => toast({ title: `${d.name} copied`, text: `Into ${l.name}.` })); } });
